# Writes brand/assets/recipes.json: compose recipes built only from the brand's blocks (python3 scripts/assets/gen-recipes.py).
import json
def at(c,r,w,h): return {"col":c,"row":r,"cols":w,"rows":h}
def B(i,t,a): return {"id":i,"type":t,"at":a}
R={}
def rec(name,group,desc,size,blocks,sample,opts=None,theme='black',grid=None,sizes=None):
    R[name]={"group":group,"description":desc,"size":size,**({"sizes":sizes} if sizes else {}),"theme":theme,**({"grid":grid} if grid else {}),"blocks":blocks,"sample":sample,"options":opts or {}}
# IAB and display ads
for s in ['ad-300x250','ad-336x280']:
    rec(s,'ad',f'Display ad at {s[3:]}: the lockup, a headline and the button.',s,[B('logo','logo',at(0,0,7,2)),B('headline','headline',at(0,3,12,5)),B('button','button',at(0,9,8,3))],{"headline.text":"Product design thinking and implementation.","button.text":"Book a call"})
rec('ad-320x50','ad','Mobile banner at 320x50: the logomark, a headline and the button in one row.','ad-320x50',[B('logo','logo',at(0,1,2,10)),B('headline','headline',at(3,0,6,12)),B('button','button',at(9,1,3,10))],{"headline.text":"Design partners.","button.text":"Book"},{"logo.lockup":"mark"})
# Wide strips: the headline sized to the strip, so it sits with the lockup (about one and a half times its height) instead
# of dwarfing it; the lockup, the words and the button share one centered row with the same margins.
for s,size in [('ad-728x90',20),('ad-970x250',30)]:
    rec(s,'ad',f'Display ad at {s[3:]}: the lockup, a headline and the button in one row.',s,[B('logo','logo',at(0,4,2,4)),B('headline','headline',at(3,2,6,8)),B('button','button',at(9,4,3,4))],{"headline.text":"Product design thinking and implementation.","button.text":"Book a call"},{"headline.size":size,"headline.valign":"center","button.align":"right","button.valign":"center"})
# Tall skyscrapers: a lockup sized to the column (not its full width) over a headline that leads.
for s,cols,size in [('ad-300x600',7,30),('ad-160x600',10,20)]:
    rec(s,'ad',f'Display ad at {s[3:]}: the lockup on top, the headline, the static and the button.',s,[B('signal','signal',at(0,6,12,3)),B('logo','logo',at(0,0,cols,1)),B('headline','headline',at(0,2,12,4)),B('button','button',at(0,10,12,2))],{"headline.text":"Product design thinking and implementation.","button.text":"Book a call"},{"signal.variant":"band","headline.size":size})
rec('meta-feed','ad','Meta feed ad: the static across the top, the headline, a line and the button.','square',[B('signal','signal',at(0,0,12,4)),B('logo','logo',at(0,5,4,1)),B('headline','headline',at(0,6,12,3)),B('body','body',at(0,9,10,1)),B('button','button',at(0,11,4,1))],{"headline.text":"Product design thinking and implementation.","body.text":"Brand, product and websites for YC startups.","button.text":"Book a call"},{"signal.variant":"band"},sizes=['square','portrait','story','facebook','linkedin'])
# Product and marketing
rec('quote-card','card','A quote in Agencidev Sans with the name and role, the static at the foot.','square',[B('signal','signal',at(0,9,12,3)),B('logo','logo',at(0,0,4,1)),B('quote','quote',at(0,2,12,6))],{"quote.text":"They shipped our brand, product and site in one partnership.","quote.name":"Alex Rivera","quote.role":"Founder, Acme"},{"signal.variant":"band"})
rec('stat-card','card','A figure, what it counts and the lockup.','square',[B('logo','logo',at(0,0,4,1)),B('stat','stat',at(0,3,12,5)),B('signal','signal',at(0,9,12,3))],{"stat.value":"6.06%","stat.label":"of each YC batch designed by Acme"},{"signal.variant":"band"})
rec('launch-card','card','A launch or changelog card: a badge, the headline, a line and the button.','square',[B('signal','signal',at(0,0,12,3)),B('badge','badge',at(0,4,4,1)),B('headline','headline',at(0,5,12,3)),B('body','body',at(0,8,10,2)),B('button','button',at(0,11,4,1))],{"badge.text":"New","headline.text":"Design systems for teams and LLMs.","body.text":"Your engineers and agents ship on-brand interfaces.","button.text":"Read more"},{"signal.variant":"band"})
rec('feature-card','card','A feature: an icon, a headline and a line on a card.','square',[B('logo','logo',at(0,0,4,1)),B('icon','icon',at(0,3,2,2)),B('headline','headline',at(0,6,12,3)),B('body','body',at(0,9,10,2))],{"headline.text":"Exploration is fast. Judgement is not.","body.text":"We explore design variants in code first, then refine them in Figma."},{"icon.name":"square"})
rec('comparison','card','A comparison table under a headline.','landscape',[B('logo','logo',at(0,0,3,1)),B('headline','headline',at(0,2,12,2)),B('table','table',at(0,5,12,6))],{"headline.text":"Two partnerships.","table.rows":"Partnership|Covers|Per month\nDesign|Product design, branding, strategy|$5,417\nDev|Full-stack development|$7,000 to $20,000"})
rec('pricing-card','card','A plan on a card: the name, the price, what it includes and the button.','square',[B('logo','logo',at(0,0,4,1)),B('card','card',at(2,2,8,9))],{"card.title":"Design partnership","card.text":"$5,417 a month.","card.items":"Weekly design sprints|Cancel anytime","card.cta":"Book a call"})
rec('event-card','card','An event or webinar: the date as a label, the title, the speaker slot and the button.','square',[B('signal','signal',at(0,0,12,3)),B('eyebrow','eyebrow',at(0,4,8,1)),B('headline','headline',at(0,5,12,3)),B('body','body',at(0,8,10,2)),B('button','button',at(0,11,4,1))],{"eyebrow.text":"June 12, 10am PT","headline.text":"Designing for agents.","body.text":"With Alex Kim, Head of growth, Acme","button.text":"Save a seat"},{"signal.variant":"band"})
rec('hiring-card','card','A hiring card: the label, the role and the button.','square',[B('signal','signal',at(0,10,12,2)),B('logo','logo',at(0,0,4,1)),B('eyebrow','eyebrow',at(0,3,8,1)),B('headline','headline',at(0,4,12,3)),B('button','button',at(0,8,4,1))],{"eyebrow.text":"Current openings","headline.text":"Product designer.","button.text":"See the role"},{"signal.variant":"band"})
rec('screenshot-card','card','A screenshot in the brand kit\'s hairline tile under a headline.','landscape',[B('logo','logo',at(0,0,3,1)),B('headline','headline',at(0,2,5,4)),B('picture','picture',at(6,1,6,10))],{"headline.text":"Product design thinking and implementation."},{"picture.treatment":"frame"})
rec('before-after','card','Two pictures side by side with a label over each.','landscape',[B('before','eyebrow',at(0,0,6,1)),B('after','eyebrow',at(6,0,6,1)),B('picture-1','picture',at(0,1,6,11)),B('picture-2','picture',at(6,1,6,11))],{"before.text":"Before","after.text":"After"},{"picture-1.treatment":"plain","picture-2.treatment":"plain"})
rec('chart-card','card','A chart from your numbers under a headline.','square',[B('logo','logo',at(0,0,4,1)),B('headline','headline',at(0,2,12,2)),B('chart','chart',at(0,5,12,6))],{"headline.text":"Releases this month.","chart.data":"Mon 12, Tue 18, Wed 30, Thu 26, Fri 34"})
rec('flow-diagram','card','Three steps as cards in a row (a flow or architecture boxes).','landscape',[B('headline','headline',at(0,0,12,2)),B('step-1','card',at(0,4,4,6)),B('step-2','card',at(4,4,4,6)),B('step-3','card',at(8,4,4,6))],{"headline.text":"How a partnership starts.","step-1.title":"Call","step-1.text":"A free strategy call.","step-2.title":"Sprint","step-2.text":"Weekly design sprints.","step-3.title":"Ship","step-3.text":"Live links, tested continuously."})
rec('customer-story','card','A customer story: the quote, a figure and the lockup (Acme, never a real customer).','landscape',[B('logo','logo',at(0,0,3,1)),B('quote','quote',at(0,2,7,9)),B('stat','stat',at(8,4,4,4))],{"quote.text":"Our product finally looks like what it does.","quote.name":"Alex Rivera","quote.role":"Founder, Acme","stat.value":"6 weeks","stat.label":"from call to launch"})
# Documents and print
rec('business-card','print','A business card at print size, bleed and safe margin kept clear.','business-card',[B('logo','logo',at(0,0,6,2)),B('name','headline',at(0,6,12,2)),B('details','body',at(0,9,12,3))],{"name.text":"Alex Rivera","details.text":"Founder, Acme. alex@acme.com"})
rec('letterhead','print','A letterhead on A4: the lockup on top and the letter under it.','a4',[B('logo','logo',at(0,0,3,1)),B('body','body',at(0,2,10,9)),B('footer','eyebrow',at(0,11,8,1))],{"body.text":"Dear Alex, thank you for meeting with us last week.","footer.text":"Acme Inc. acme.com"})
rec('one-pager','print','A one-pager on A4: headline, a line, a figure, a list and a picture.','a4',[B('logo','logo',at(0,0,3,1)),B('headline','headline',at(0,1,12,2)),B('body','body',at(0,3,10,1)),B('picture','picture',at(0,5,7,5)),B('stat','stat',at(8,5,4,2)),B('list','list',at(8,7,4,3))],{"headline.text":"Product design thinking and implementation.","body.text":"Search the ads every brand runs, across every network.","stat.value":"6.06%","stat.label":"more launches tracked","list.items":"Every network|Daily updates|Shared boards"},{"picture.treatment":"plain"})
rec('report-cover','print','A report cover on A4: the static and the title.','a4',[B('signal','signal',at(0,0,12,6)),B('logo','logo',at(0,11,3,1)),B('headline','headline',at(0,7,12,3)),B('eyebrow','eyebrow',at(0,10,8,1))],{"headline.text":"Designing for agents, 2026.","eyebrow.text":"Annual report"},{"signal.variant":"field"})
rec('certificate','print','A certificate on A4: the label, the name and a line.','a4',[B('logo','logo',at(4,0,4,1)),B('eyebrow','eyebrow',at(3,3,6,1)),B('name','headline',at(1,4,10,2)),B('body','body',at(2,7,8,2))],{"eyebrow.text":"Certificate of completion","name.text":"Alex Rivera","body.text":"Design systems, level one."},{"eyebrow.align":"center","name.align":"center","body.align":"center"})
rec('email-header','email','An email header: the lockup, a headline and the static at the right.','email',[B('signal','signal',at(6,0,6,12)),B('logo','logo',at(0,0,3,2)),B('headline','headline',at(0,4,6,6))],{"headline.text":"What we shipped this month."},{"signal.variant":"band"})
rec('email-signature','email','An email signature: the lockup, the name and the details.','email-signature',[B('logo','logo',at(0,2,3,8)),B('name','body',at(4,1,8,5)),B('details','body',at(4,6,8,5))],{"name.text":"Alex Rivera","details.text":"Founder, Acme"})
rec('event-badge','print','An event badge: the lockup, the name and the role.','portrait',[B('signal','signal',at(0,0,12,3)),B('logo','logo',at(0,4,5,1)),B('name','headline',at(0,6,12,3)),B('role','body',at(0,9,12,2))],{"name.text":"Alex Rivera","role.text":"Founder, Acme"},{"signal.variant":"band"})
# Backgrounds
rec('meeting-background','background','A video-call background: the lockup and the static at the sides, the middle clear for the person.','meeting',[B('signal','signal',at(0,0,3,12)),B('logo','logo',at(9,0,3,1))],{},{"signal.variant":"field"})
rec('desktop-wallpaper','background','A desktop wallpaper: the static across the lower half, the lockup small.','desktop',[B('signal','signal',at(0,6,12,6)),B('logo','logo',at(0,0,2,1))],{},{"signal.variant":"band"})
rec('phone-wallpaper','background','A phone wallpaper: the static across the lower half, the lockup small.','phone-wallpaper',[B('signal','signal',at(0,6,12,6)),B('logo','logo',at(4,2,4,1))],{},{"signal.variant":"field"})
json.dump({"$comment":"Compose recipes: ready layouts of the brand's blocks, drawn in the site's materials (its greys, square tiles, the plate button and the 404 page's no-signal static), for the graphics no template covers (display ads, cards, documents, print, email, backgrounds). `recipe <name>` writes a compose design file from one and draws it; the words are yours (--set block.slot=..., or --sample for the sample copy below, Acme only). Every recipe draws clean at its size with its sample copy (test/recipes.test.ts).","recipes":R},open(__import__('os').path.join(__import__('os').path.dirname(__file__), '..', '..', 'brand', 'assets', 'recipes.json'), 'w'),indent=1)
print(len(R))
